<?php $pageTitle='Admin Panel';require __DIR__.'/header.php';?><h1>Hospital Administration</h1><div class="admin"><section class="card"><h2>Add Doctor</h2><form method="post" action="index.php?action=save_doctor"><div class="grid2"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone" required></label><label>Password<input name="password" value="doctor123"></label><label>Department<select name="department_id" required><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></label><label>Specialization<input name="specialization" required></label><label>Fee<input type="number" step=".01" name="fee" required></label><label>Available Days<input name="available_days" placeholder="Sat, Mon, Wed" required></label><label>Start<input type="time" name="start_time" required></label><label>End<input type="time" name="end_time" required></label><label>Room<input name="room" required></label></div><button class="btn primary">Add Doctor</button></form></section><section class="card"><h2>Departments</h2><form method="post" action="index.php?action=save_department"><input name="name" placeholder="Department name" required><button class="btn primary">Add</button></form><ul><?php foreach($departments as $d):?><li><?=htmlspecialchars($d['name'])?> <a class="danger" href="index.php?action=delete_department&id=<?=$d['id']?>">delete</a></li><?php endforeach;?></ul></section></div><section class="card table"><h2>Doctors</h2><table><tr><th>Name</th><th>Department</th><th>Specialization</th><th>Fee</th><th>Action</th></tr><?php foreach($doctors as $d):?><tr><td>Dr. <?=htmlspecialchars($d['name'])?></td><td><?=$d['department_name']?></td><td><?=$d['specialization']?></td><td>৳<?=number_format($d['fee'],2)?></td><td><a class="danger" href="index.php?action=delete_doctor&id=<?=$d['id']?>" onclick="return confirm('Remove doctor?')">Remove</a></td></tr><?php endforeach;?></table></section><section class="card table"><h2>All Appointments</h2><form class="filters"><input type="date" name="date" value="<?=htmlspecialchars($_GET['date']??'')?>"><select name="doctor_id"><option value="">All doctors</option><?php foreach($doctors as $d):?><option value="<?=$d['id']?>">Dr. <?=$d['name']?></option><?php endforeach;?></select><input type="hidden" name="action" value="admin"><button class="btn">Filter</button></form><table><tr><th>Date</th><th>Serial</th><th>Patient</th><th>Doctor</th><th>Status</th></tr><?php foreach($appointments as $a):?><tr><td><?=$a['appointment_date']?></td><td>#<?=$a['serial_no']?></td><td><?=$a['patient_name']?></td><td>Dr. <?=$a['doctor_name']?></td><td><?=$a['status']?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/footer.php';?>